"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisFaqContent } from "./components/faq-blocks/content";
import View1 from "./components/faq-blocks/variants/02-ai-workspace";
const variants = {"ai-workspace":View1};
export type { ArtemisFaqContact, ArtemisFaqContent, ArtemisFaqLink, ArtemisFaqQuestion, ArtemisFaqSearch } from "./components/faq-blocks/content";
export interface ArtemisFaqBlocksProps { className?: string; variant?: "ai-workspace"; /** The words on the FAQ section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisFaqContent>; }
export function ArtemisFaqBlocks({ className, variant = "ai-workspace", content }: ArtemisFaqBlocksProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal

/** The words on a button or link, and where it goes. */
export interface ArtemisFaqLink {
  label: string;
  href: string;
}

/** A question and its answer. */
export interface ArtemisFaqQuestion {
  /** The question, on the row that opens. */
  question: string;
  /** The answer, shown while the row is open. */
  answer: string;
  /** A short slug, unique in the list, used in the row's element ids. Defaults to the row's position. */
  id?: string;
  /** The topic it belongs to. search shows it on the row and adds a filter tab for each topic, in the order the topics first appear; with no topics it shows no tabs. */
  category?: string;
}

/** A card beside the questions that points to a person. */
export interface ArtemisFaqContact {
  /** A small line over the title. split. */
  label?: string;
  /** The card's heading. */
  title: string;
  /** The paragraph under the heading. */
  description: string;
  /** The card's button. */
  cta: ArtemisFaqLink;
}

/** The words on the search box, its topic tabs and its empty result. */
export interface ArtemisFaqSearch {
  /** The hint in the empty search box. */
  placeholder: string;
  /** The first topic tab, which shows every question. */
  allLabel: string;
  /** The heading shown when no question matches. */
  emptyTitle: string;
  /** The line under that heading. */
  emptyText: string;
}

/** The words on an Artemis FAQ section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisFaqContent {
  /** The short line above the heading. All layouts. */
  badge: string;
  /** The heading. All layouts. */
  headline: string;
  /** The heading's last words. stacked underlines them; the other layouts run them on after `headline`. Left out, it keeps the layout's own only when `headline` is left out too. */
  headlineAccent?: string;
  /** The paragraph under the heading. All layouts. */
  subhead: string;
  /** The questions, each opening to show its answer. All layouts. numbered and split number them; numbered, ai-workspace, split and search open one at a time, starting with the first; stacked opens any number, starting with the first two. */
  questions: ArtemisFaqQuestion[];
  /** A card with a button beside the questions. ai-workspace and split. */
  contact?: ArtemisFaqContact;
  /** The words on the search box, the topic tabs and the empty result. search. */
  search?: ArtemisFaqSearch;
}

"use client";
// @zeus-internal
import { useId, useState } from "react";
import { Dithering } from "@paper-design/shaders-react";
import { motion, useReducedMotion } from "motion/react";
import { ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { ArtemisButton } from "../../../foundations/button";
import type { ArtemisFaqContent } from "../content";
const DEFAULT = {
    badge: "AI workspace FAQ",
    headline: "Build with AI, without the guesswork",
    subhead: "Models, private data, agent tools, and what your team controls from day one.",
    questions: [
        { id: "model-choice", question: "Which AI models can I use?", answer: "Start with hosted models or connect your preferred provider. Model routing stays configurable, so the underlying workflow does not need to be rebuilt when requirements change." },
        { id: "private-data", question: "Can AI work with private company data?", answer: "Yes. Connect approved sources through retrieval and permission-aware tools, while keeping access scoped to the people and agents that need it." },
        { id: "agent-tools", question: "How do agents connect to tools?", answer: "Agents can call APIs, databases, and internal services through explicit tool definitions. Each connection can use its own credentials, limits, and approval rules." },
        { id: "first-workflow", question: "Can I start with one workflow?", answer: "Yes. Begin with one narrow, measurable task, review its outputs with the team, and expand only after the workflow proves useful." },
        { id: "observability", question: "How can I monitor quality and cost?", answer: "Use traces, evaluations, latency, token usage, and cost limits to understand every run. Failed steps remain visible instead of disappearing inside a black box." },
    ],
    contact: {
        title: "Planning an AI workflow?",
        description: "Share the use case, current stack, and constraints to identify the best place to start.",
        cta: { label: "Review your AI plan", href: "#contact" },
    },
} satisfies ArtemisFaqContent;
export default function FaqBlocksAiWorkspace({ content }: { content?: Partial<ArtemisFaqContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const baseId = useId();
    const reduce = useReducedMotion();
    const [active, setActive] = useState<number | null>(0);
    return (<>
      <section className="art:w-full art:bg-background art:px-4 art:py-16 art:font-sans art:text-foreground art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:py-24">
        <div className="art:mx-auto art:w-full art:max-w-6xl">
          <header className="art:mx-auto art:max-w-xl art:text-center">
            <p className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-widest">
              {copy.badge}
            </p>
            <h2 className="art:mt-5 art:text-balance art:font-medium art:text-4xl art:leading-none art:tracking-tight">
              {copy.headlineAccent ? `${copy.headline} ${copy.headlineAccent}` : copy.headline}
            </h2>
            <p className="art:mx-auto art:mt-5 art:max-w-md art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:@min-[640px]/artemis:text-base">
              {copy.subhead}
            </p>
          </header>
          <div className="art:relative art:mt-12 art:isolate art:overflow-hidden art:rounded-3xl art:border art:border-border/60 art:p-4 art:@min-[640px]/artemis:p-6 art:@min-[1024px]/artemis:p-8">
            <div aria-hidden="true" className="art:absolute art:inset-0 art:-z-20">
              <Dithering className="art:absolute art:inset-0 art:size-full" colorBack="#0f766e" colorFront="#fb923c" shape="wave" type="4x4" size={3} scale={1.15} speed={reduce ? 0 : 0.12}/>
            </div>
            <div aria-hidden="true" className="art:absolute art:inset-0 art:-z-10 art:bg-background/15 art:backdrop-saturate-150 art:dark:bg-background/30"/>
            <div className="art:grid art:items-start art:gap-4 art:@min-[1024px]/artemis:grid-cols-[0.78fr_1.22fr] art:@min-[1024px]/artemis:gap-5">
              <aside className="art:rounded-3xl art:border art:border-border/60 art:bg-background/80 art:p-6 art:backdrop-blur-2xl art:backdrop-saturate-150 art:@min-[640px]/artemis:p-7">
                <p className="art:font-medium art:text-xl">
                  {copy.contact.title}
                </p>
                <p className="art:mt-3 art:max-w-sm art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">
                  {copy.contact.description}
                </p>
                <motion.a whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:mt-6 art:h-9 art:rounded-full" href={copy.contact.cta.href} tabIndex={0}>
                  {copy.contact.cta.label}
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-3.5" aria-hidden="true">
                    <path d="M7 7h10v10"/>
                    <path d="M7 17 17 7"/>
                  </svg>
                </motion.a>
              </aside>
              <div className="art:flex art:flex-col art:gap-3">
                {copy.questions.map((item, index) => {
                const id = item.id ?? `q${index}`;
                const open = active === index;
                return (<article key={id} className="art:overflow-hidden art:rounded-3xl art:border art:border-border/60 art:bg-background/80 art:backdrop-blur-2xl art:backdrop-saturate-150">
                  <ArtemisButton variant="link" size="none" className="art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:group art:flex art:min-h-20 art:w-full art:items-start art:gap-4 art:px-5 art:py-5 art:text-left art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-inset art:focus-visible:ring-ring art:@min-[640px]/artemis:px-6 art:rounded-full" id={`${baseId}-${id}-trigger`} aria-expanded={open} aria-controls={`${baseId}-${id}-content`} onClick={() => setActive(open ? null : index)} tabIndex={0}>
                    <span className="art:min-w-0 art:flex-1 art:font-medium art:text-xl art:leading-7">
                      {item.question}
                    </span>
                    <span aria-hidden="true" className="art:grid art:size-10 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted art:text-foreground">
                      <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-plus art:size-4 art:transition-transform art:duration-200 art:motion-reduce:transition-none ${open ? "art:rotate-45" : ""}`} aria-hidden="true" style={{ transitionTimingFunction: "cubic-bezier(0.16, 1, 0.3, 1)" }}>
                        <path d="M5 12h14"/>
                        <path d="M12 5v14"/>
                      </svg>
                    </span>
                  </ArtemisButton>
                  <section id={`${baseId}-${id}-content`} aria-labelledby={`${baseId}-${id}-trigger`} aria-hidden={!open} style={{ transitionTimingFunction: "cubic-bezier(0.16, 1, 0.3, 1)" }} className={`art:grid art:overflow-hidden art:transition-[grid-template-rows] art:duration-200 art:motion-reduce:transition-none ${open ? "art:grid-rows-[1fr]" : "art:grid-rows-[0fr]"}`}>
                    <div className="art:min-h-0 art:overflow-hidden">
                      <p style={{ transitionTimingFunction: "cubic-bezier(0.16, 1, 0.3, 1)" }} className={`art:pr-6 art:pb-6 art:pl-5 art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:transition-[opacity,transform] art:duration-200 art:motion-reduce:transition-none art:@min-[640px]/artemis:pr-16 art:@min-[640px]/artemis:pl-6 ${open ? "art:translate-y-0 art:opacity-100" : "art:-translate-y-1 art:opacity-0"}`}>
                        {item.answer}
                      </p>
                    </div>
                  </section>
                </article>);
                })}
              </div>
            </div>
          </div>
        </div>
      </section>
    </>);
}
